#include <string.h>
#include <limits.h>

#define MAX_STATIONS 105
#define INF 1000000000

int n, m;
int dist[MAX_STATIONS][MAX_STATIONS];

void floyd_warshall() {
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (dist[i][k] == INF) continue;
            for (int j = 0; j < n; j++) {
                if (dist[k][j] == INF) continue;
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
}

int main() {
    while (1) {
        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) break;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) dist[i][j] = 0;
                else dist[i][j] = INF;
            }
        }

        for (int i = 0; i < m; i++) {
            int a, b, d, t;
            scanf("%d %d %d %d", &a, &b, &d, &t);
            a--; b--;
            int cost = d + t;
            if (cost < dist[a][b]) {
                dist[a][b] = cost;
