#define INF 1e18
#define MAXN 1005
#define MAXM 100005

typedef struct { int to, next; double w; } Edge;
Edge edges[MAXM*2];
int head[MAXN], cnt;
double dist[MAXN];
int visited[MAXN];

void addEdge(int u, int v, double w) {
    edges[cnt] = (Edge){v, head[u], w};
    head[u] = cnt++;
    edges[cnt] = (Edge){u, head[v], w};
    head[v] = cnt++;
}

void dijkstra(int src, int n) {
    for (int i = 0; i <= n; i++) dist[i] = INF, visited[i] = 0;
    dist[src] = 0;
    for (int i = 0; i < n; i++) {
        int u = -1;
        for (int j = 1; j <= n; j++)
            if (!visited[j] && (u == -1 || dist[j] < dist[u])) u = j;
        if (u == -1 || dist[u] == INF) break;
        visited[u] = 1;
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (dist[u] + edges[e].w < dist[v])
                dist[v] = dist[u] + edges[e].w;
        }
    }
}

