typedef long long ll;

typedef struct Edge {
    int to;
    int next;
    ll w;
} Edge;

typedef struct Node {
    ll d;
    int v;
} Node;

typedef struct Heap {
    Node *a;
    int sz;
} Heap;

static void heap_push(Heap *h, ll d, int v) {
    int i = ++h->sz;
    while (i > 1) {
        int p = i >> 1;
        if (h->a[p].d <= d) break;
        h->a[i] = h->a[p];
        i = p;
    }
    h->a[i].d = d;
    h->a[i].v = v;
}

static Node heap_pop(Heap *h) {
    Node ret = h->a[1];
    Node last = h->a[h->sz--];
    int i = 1;
    while ((i << 1) <= h->sz) {
        int l = i << 1, r = l + 1, c = l;
        if (r <= h->sz && h->a[r].d < h->a[l].d) c = r;
        if (h->a[c].d >= last.d) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static void dijkstra(int n, int start, int *head, Edge *edges, ll *dist, int edgeCount) {
    const ll INF = (1LL << 60);
    for (int i = 0; i < n; i++) dist[i] = INF;
    dist[start] = 0;

    Heap h;
    h.a = (Node *)malloc(sizeof(Node) * (edgeCount + n + 5));
    h.sz = 0;
    heap_push(&h, 0, start);

    while (h.sz) {
        Node cur = heap_pop(&h);
        ll cd = cur.d;
        int v = cur.v;
        if (cd != dist[v]) continue;

        for (int ei = head[v]; ei != -1; ei = edges[ei].next) {
            int to = edges[ei].to;
            ll nd = cd + edges[ei].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(&h, nd, to);
            }
        }
    }

    free(h.a);
}

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        int s, t, g;
        scanf("%d %d %d", &s, &t, &g);
        s--; t--; g--;

        int *head = (int *)malloc(sizeof(int) * n);
        for (int i = 0; i < n; i++) head[i] = -1;

        Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * m));
        int ec = 0;

        for (int i = 0; i < m; i++) {
            int a, b;
            ll d, delay;
            scanf("%d %d %lld %lld", &a, &b, &d, &delay);
            a--; b--;
            ll w = d + delay;

            edges[ec].to = b;
            edges[ec].w = w;
            edges[ec].next = head[a];
            head[a] = ec++;

            edges[ec].to = a;
            edges[ec].w = w;
            edges[ec].next = head[b];
            head[b] = ec++;
        }

        ll *distS = (ll *)malloc(sizeof(ll) * n);
        ll *distT = (ll *)malloc(sizeof(ll) * n);
        ll *distG = (ll *)malloc(sizeof(ll) * n);

        dijkstra(n, s, head, edges, distS, ec);
        dijkstra(n, t, head, edges, distT, ec);
        dijkstra(n, g, head, edges, distG, ec);

        ll ans = (1LL << 60);
        for (int i = 0; i < n; i++) {
            if (distS[i] >= (1LL << 60) || distT[i] >= (1LL << 60) || distG[i] >= (1LL << 60)) continue;
            ll total = distS[i] + distT[i] + distG[i];
            if (total < ans) ans = total;
        }

        printf("%lld\n", ans);

        free(head);
        free(edges);
        free(distS);
        free(distT);
        free(distG);
    }
    return 0;
}

