            pq.pop();

            if (d > dist_from_start[u]) continue;

            for (auto& e : graph[u]) {
                long long time = d + calculateTime(e.dist, e.delay);
                if (time < dist_from_start[e.to]) {
                    dist_from_start[e.to] = time;
