import java.util.*;

public class Main {
    static class Edge {
        int to;
        int distance;
        int delay;

        Edge(int to, int distance, int delay) {
            this.to = to;
            this.distance = distance;
            this.delay = delay;
        }
    }

    static class Node implements Comparable<Node> {
        int id;
        long time;

        Node(int id, long time) {
            this.id = id;
            this.time = time;
        }

        @Override
        public int compareTo(Node other) {
            return Long.compare(this.time, other.time);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNext()) {
            int N = sc.nextInt();
            int M = sc.nextInt();
            int S = sc.nextInt();
            int F = sc.nextInt();
            int T = sc.nextInt();

            if (N == 0 && M == 0 && S == 0 && F == 0 && T == 0) break;

            // Build graph
            List<List<Edge>> graph = new ArrayList<>();
            for (int i = 0; i <= N; i++) {
                graph.add(new ArrayList<>());
            }

            for (int i = 0; i < M; i++) {
                int a = sc.nextInt();
                int b = sc.nextInt();
                int d = sc.nextInt();
                int t = sc.nextInt();
                graph.get(a).add(new Edge(b, d, t));
                graph.get(b).add(new Edge(a, d, t));
            }

            // Dijkstra from S to all nodes
            long[] distFromS = dijkstra(graph, S, N);

            // Dijkstra from F to all nodes
            long[] distFromF = dijkstra(graph, F, N);

            // Check if path exists
            if (distFromS[F] == Long.MAX_VALUE || distFromF[T] == Long.MAX_VALUE) {
                System.out.println(-1);
                continue;
            }

            long totalTime = distFromS[F] + distFromF[T];
            System.out.println(totalTime);
        }

        sc.close();
    }

    static long[] dijkstra(List<List<Edge>> graph, int start, int N) {
        long[] dist = new long[N + 1];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;

        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.offer(new Node(start, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();

            if (current.time > dist[current.id]) continue;

            for (Edge edge : graph.get(current.id)) {
                long newTime = current.time + edge.distance + edge.delay;
                if (newTime < dist[edge.to]) {
                    dist[edge.to] = newTime;
                    pq.offer(new Node(edge.to, newTime));
                }
            }
        }

        return dist;
    }
}

