/*
 * AOJ-style multiple datasets.
 *
 * We have an undirected weighted graph.
 * Need minimum travel time:
 *   start -> friend -> destination
 * where each edge has:
 *   distance x
 *   delay y
 * and travel time on that edge is x / 40.0 + y / 60.0 hours
 * (Seishun 18 ticket local-train style: distance converted at 40 km/h, delay in minutes)
 *
 * Input format (reconstructed from statement):
 *   n m
 *   s t g
 *   u v x y   (m lines)
 * repeated until n = 0
 *
 * Output:
 *   minimum time in hours
 *
 * Since the original statement says "output being the total travel time in hours",
 * we print as a real number with 10 digits after decimal point.
 */
public class Main {
    static class Edge {
        int to;
        double cost;
        Edge(int to, double cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        double d;
        Node(int v, double d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Double.compare(this.d, o.d);
        }
    }

    static double[] dijkstra(List<Edge>[] g, int s) {
        int n = g.length;
        double[] dist = new double[n];
        Arrays.fill(dist, Double.POSITIVE_INFINITY);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[s] = 0.0;
        pq.add(new Node(s, 0.0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d > dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                double nd = cur.d + e.cost;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == Integer.MIN_VALUE) break;
            if (n == 0) break;
            int m = fs.nextInt();

            int start = fs.nextInt() - 1;
            int friend = fs.nextInt() - 1;
            int goal = fs.nextInt() - 1;

            List<Edge>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int a = fs.nextInt() - 1;
                int b = fs.nextInt() - 1;
                double x = fs.nextInt(); // distance
                double y = fs.nextInt(); // delay
                double cost = x / 40.0 + y / 60.0;
                g[a].add(new Edge(b, cost));
                g[b].add(new Edge(a, cost));
            }

            double[] ds = dijkstra(g, start);
            double[] df = dijkstra(g, friend);
            double ans = ds[friend] + df[goal];

            out.append(String.format(Locale.US, "%.10f%n", ans));
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
